var KnownResources = []string{"card:0", "memory", "awake"}

var ResourceErrorCodes = []string{"internal", "invalid_request", "caller_refused", "unknown_resource", "policy_unavailable", "forbidden"}

// program and account are the subject as rights names it: an absolute image
// path or a package family, and a Windows SID or POSIX uid. amount is bytes.
// lease is set when the hold is a lease of lease@1; grant names the rights rule
// it sits under and is empty for a holder that never asked. detail is what the
// holder says it holds, such as a host's model name; it is a claim.
type Holder struct {
	Program  string
	Account  string
	Amount   int64
	Evidence Evidence
	Lease    string
	Grant    string
	Since    string
	Detail   string
}

// capacity is bytes, 0 when the instrument cannot say. held is the sum of
// verified amounts only. instrument names what measured: windows-gpu-counters,
// linux-fdinfo, metal-working-set, which measures capacity and no holder, or
// none. Under metal-working-set or none every holder is claimed.
type ResourceState struct {
	Resource   string
	Capacity   int64
	Held       int64
	Holders    []Holder
	Observed   string
	Instrument string
}

// state is present exactly for ok. A forbidden outcome does not reveal another
// program's rows.
type HoldersResult struct {
	Outcome ResourceCallOutcome
	State   *ResourceState
}

type ResourceList struct {
	Resources []string
	Observed  string
}

// list is present exactly for ok.
type ResourcesResult struct {
	Outcome ResourceCallOutcome
	List    *ResourceList
}

// amount is the requested admission reservation, not a physical memory quota. A
// [Lease](https://openabstractions.github.io/reference.html#concept-resource.lease)
// not renewed by renew_by is released; the holder's bytes are then reported as
// a holder without a lease until the instrument stops seeing them.
type Lease struct {
	ID       string
	Resource string
	Amount   int64
	Since    string
	RenewBy  string
}

// One holder asked during Acquire: yielded, refused, or unanswered within the
// wait, with the reason a refusal gave.
type YieldRecord struct {
	Holder string
	Amount int64
	Answer string
	TookMs int64
}

// lease is present exactly for acquired. asked lists every holder the service
// asked to yield for this request, in order, whatever the outcome.
type AcquireResult struct {
	Outcome AcquireOutcome
	Lease   *Lease
	Asked   []YieldRecord
}

// lease is present exactly for acquired. asked is always empty: AcquireFree
// asks nobody to yield. Its outcomes belong to this new method; Acquire retains
// its published closed vocabulary.
type AcquireFreeResult struct {
	Outcome AcquireFreeOutcome
	Lease   *Lease
	Asked   []YieldRecord
}

// A request that this holder give back the named lease of amount bytes of
// resource. reason names the program that asked, as rights names it.
type YieldRequest struct {
	ID       string
	Resource string
	Amount   int64
	Reason   string
	At       string
	Lease    string
}

type YieldPage struct {
	Requests []YieldRequest
	Next     string
}

// page is present exactly for ok.
type ObserveResult struct {
	Outcome ResourceCallOutcome
	Page    *YieldPage
}

type AnswerResult struct {
	Recorded bool
}

// answer is present exactly for ok.
type AnswerCallResult struct {
	Outcome ResourceCallOutcome
	Answer  *AnswerResult
}

type LeaseChange struct {
	Applied bool
	Lease   *Lease
}

// change is present exactly for ok; applied false retains the idempotent result
// for a lease not held by the caller.
type LeaseChangeResult struct {
	Outcome ResourceCallOutcome
	Change  *LeaseChange
}

// bound permits a verified child process's measured bytes to offset this
// lease's admission reservation. unverifiable and refused leave the full
// reservation in place; no process identity is published in the holder table.
type ProcessBindResult struct {
	Outcome ProcessBindOutcome
}

// The one refusal record every OA service carries beside a refusing outcome
// (RIGHTS-E3; conventions CONV-E4). source names the authority that refused:
// rights, credentials, license, terms, identity or os. decision is denied for
// an explicit refusal, not_granted where no rule permits, and person_only where
// only the person may answer the question. ask says whether asking can change
// the answer: available, or none. action is the exact registered
// <owner>/<name>; question the pending question's id; credential the
// credential's name; retry_after_ms the earliest useful retry in milliseconds,
// omitted when zero. Stop asking is denied with ask none. Current carriers
// include config@2, messages@1, registry@3, endpoint@2 and chat@3, declared in
// config.thrift, messages.thrift, registration.thrift and inference.thrift.
// Other services adopt it in their scheduled versions.
type EndpointRefusalDetail struct {
	Source       EndpointRefusalSource
	Decision     EndpointRefusalDecision
	Ask          EndpointRefusalAsk
	Action       string
	Question     string
	Credential   string
	RetryAfterMs int64
}

// Producer assertion validated by the runtime. Kind is the governed open
// build-time vocabulary <owner>/<name>, not a display string or an authority
// claim. copy identifies one copy within the kind. reason follows D87
// domain:word:detail as open display text. checked is the producer's claimed
// check time. Custom/unknown copies are unverified; readiness remains
// independent. No runtime kind-registration method is introduced.
type EndpointProducerCheck struct {
	Kind    string
	Copy    string
	State   EndpointProducerCheckState
	Reason  string
	Checked string
}

// endpoint@2 service observation. definition_hash is sha256: plus64 lowercase
// hex over this service version's canonical wire form (CONV-V2), verified by
// the definition-hash owner. reason retains readiness errors and is empty when
// ready. capabilities remain display-only. Program-level producer checks belong
// to EndpointDescription and are independent of service readiness.
type EndpointServiceState struct {
	Service        string
	Readiness      EndpointServiceReadiness
	Reason         string
	Guarantees     []string
	Capabilities   map[string]string
	DefinitionHash string
}

// Complete endpoint@2 description with each advertised service's definition
// hash and one program-level producer-check list. Checks are independent of
// service readiness; absence means unobserved, never verified.
// Forbidden/unavailable authority refusals carry the single Rights-owned
// EndpointRefusalDetail; other outcomes omit it. Unsupported carries the
// existing bounded reason with D87 unsupported:not_implemented words; no closed
// staged-reason vocabulary is frozen. Non-described replies disclose no
// program/version/services/checks. Endpoint@1 and its closed
// EndpointDescription/EndpointServiceState remain unchanged. The compact value
// ceiling excluding insignificant JSON whitespace is IPC-F1; an oversized whole
// reply is unavailable/bound:reply_bytes without truncation.
type EndpointDescription struct {
	Outcome  EndpointDescriptionOutcome
	Program  string
	Version  string
	Services []EndpointServiceState
	Refusal  *EndpointRefusalDetail
	Reason   string
	Checks   []EndpointProducerCheck
}

type EndpointDescriptionResult struct {
	Value EndpointDescription
}

